658	    &self,
659	    app: &AppHandle<R>,
660	    key: &ScopeKey,
661	  ) -> crate::Result<ScopeValue<T>> {
662	    let cache = self.command_cache.get(key).unwrap();
663	    match cache.try_get::<ScopeValue<T>>() {
664	      Some(cached) => Ok(cached.clone()),
665	      None => {
666	        let resolved_scope = self
667	          .command_scope
668	          .get(key)
669	          .unwrap_or_else(|| panic!("missing command scope for key {key}"));
670	
