// converts the temporary resolved commands into their final representation,
// parsing the collected window and webview glob patterns.
fn resolve_commands(
  commands: BTreeMap<String, Vec<ResolvedCommandTemp>>,
) -> Result<BTreeMap<String, Vec<ResolvedCommand>>, Error> {
  let mut resolved = BTreeMap::new();

  for (name, temps) in commands {
    let mut resolved_commands = Vec::new();
    for temp in temps {
      resolved_commands.push(ResolvedCommand {
        #[cfg(debug_assertions)]
        referenced_by: temp.referenced_by,
        context: temp.context,
        windows: parse_glob_patterns(temp.windows)?,
        webviews: parse_glob_patterns(temp.webviews)?,
        scope_id: temp.scope_id,
      });
    }
    resolved.insert(name, resolved_commands);
  }

  Ok(resolved)
